\entrytitle{16}{Minimum linear arrangement}{strengthPolynomial}{evidencePartial}{hardwareExponential}
\setcounter{problem}{15}
\begin{problem}[Minimum linear arrangement]
For $G=(V,E)$, compute $\min_\pi\sum_{uv\in E}|\pi(u)-\pi(v)|$ over bijections $\pi:V\to[n]$. The sum measures total edge length in a linear layout and models total wiring length or aggregate communication distance.
The quantum comparison uses QRAM time and the classical comparison uses RAM operations on the graph.
\end{problem}
\speedupheading
\complexity{Quantum}{$O^*(1.817^n)$, quantum vertex-ordering dynamic programming.}
The sum of edge lengths equals the sum of cut sizes over the prefixes of the ordering. This additive objective fits the ordering recurrence, with polynomial-time evaluation of each transition. The quantum algorithm uses nested minimum finding and coherent access to partially precomputed subset values.
\complexity{Classical}{$O^*(2^n)$, subset dynamic programming.}
For each subset, the recurrence minimizes its accumulated prefix-cut cost over choices of the last vertex. Straightforward implementations include an $O(m2^n)$ bound, with polynomial factors depending on the graph representation, and use exponential memory. Specialized graph classes, including trees, admit faster classical algorithms and are separate input regimes.
\dimensionlabel{Strength}{strengthPolynomial} Polynomial speedup through a smaller exponential constant, obtained from amplitude amplification and quantum minimum finding.
\dimensionlabel{Evidence}{evidencePartial} Rigorous QRAM upper bound; partial evidence relative to the best general classical exact-algorithm comparison.
\dimensionlabel{Hardware}{hardwareExponential} A subset needs $n$ active qubits and the objective needs $O(\log(nm))$ bits, with reversible workspace and exponential coherent table storage. Fault tolerance is needed for useful depths.
\subhead{Algorithm}
\begin{algorithmindex}{16}
\item \href{https://arxiv.org/pdf/1807.05209}{Ambainis et al., \emph{Quantum Speedups for Exponential-Time Dynamic Programming Algorithms} (SODA 2019)}. Corollary 5 and equation (3): additive vertex-ordering recurrence and minimum-linear-arrangement application.
\item \href{https://doi.org/10.1007/s00224-011-9312-0}{Bodlaender et al., \emph{A Note on Exact Algorithms for Vertex Ordering Problems on Graphs} (2012)}. The subset dynamic-programming construction for additive ordering objectives.
\end{algorithmindex}
